    {
      "id": "N2",
      "quote": "Future owner supplies INV-SERVICE-READY evidence as defined in environment.md; otherwise W3/W4 remain blocked and no remote action occurs.",
      "locator": "plans[0].final.assumptions, A4 settle",
      "grade": 2,
      "reason": "The named prerequisite has a future inventory service owner and requires an approved isolated sandbox, primary contract evidence and verified service primitives. W4 integration depends on that evidence and authority; general activation additionally awaits actual-command live acceptance."
    },
    {
      "id": "N3",
      "quote": "Ready: W1 validator and test_TC_V01–V03 evidence accepted; service readiness is not required.",
      "locator": "plans[0].final.work_items, W2 context",
      "grade": 2,
      "reason": "W1 validation and W2 preview remain independently eligible. Their local schema is explicitly provisional, preview reports not-published status, and publication fails closed. No endpoint, credential or provisioning permission is invented."
    },
    {
      "id": "N4",
      "quote": "After integration, S01–S04 remain due on the actual command and approved service, including success, partial failure, interrupted publication and recovery.",
      "locator": "planning_artifacts: docs/shiploop/environment.md, External prerequisite INV-SERVICE-READY",
      "grade": 2,
      "reason": "S01–S04 retain live success, server-side partial failure, interruptions around commit, retry identity and recovery checks with independent observations. W1/W2/W4 preserve the existing offline behavior and require regression passes. Only the baseline was executed; future acceptance is explicitly unrun."
    },
    {
      "id": "N5",
      "quote": "No experiment selected, no scratch prototype, no external call.",
      "locator": "planning_artifacts: planning-investigation.md, Decision frontier",
      "grade": 2,
      "reason": "The supplied traces show no doomed connectivity investigation or simulated atomicity experiment. Source inspection settles why the transport cannot reveal service semantics. Baseline and selector checks establish useful local runner facts without claiming remote evidence. Zero capability experiments is appropriate."
    }
  ],
  "false_readiness": [],
  "initial_unsupported_commitments": [],
  "decision_rework": [
    {
      "before": "Publication stays disabled pending live evidence and any additional activation authority.",
      "after": "General publication activation stays disabled pending live evidence and any additional activation authority.",
      "consequence": "The final W4 explicitly distinguishes future authorized sandbox execution from general activation. Its incremental decision value is uncertain: the seed already required actual-command live tests and stated that live cases have a separately approved opt-in route. The revision reduces ambiguity, but no dependency, service assumption or acceptance obligation demonstrably changed.",
      "value": "uncertain"
    }
  ],
  "unnecessary_investigation": [
    {
      "event_or_locator": "application_tool_evidence event 110, backchain-check portion; compare event 86",
      "reason": "The structural checker reran against the identical graph digest after a prose-only gate clarification. It could not resolve that authorization ambiguity and added no new dependency evidence. This is minor redundant checking, distinct from the useful source inspection, baseline execution and document checks."
    }
  ],
  "evidence_timing": [
    {
      "decision": "Do not infer external atomicity or readiness from the offline transport failure.",
      "first_supported_at": "supplied",
      "basis": "The request and supplied src/client.py explicitly establish failure before any request. Event 15 inspects that source during test-strategy; no experiment was needed."
    },
    {
      "decision": "Keep independent local validation and preview eligible while service work remains conditional.",
      "first_supported_at": "supplied",
      "basis": "The case request explicitly requires this separation. Test-strategy artifacts already preserve it before the producer seed."
    },
    {
      "decision": "Use the owner-supplied INV-SERVICE-READY prerequisite for integration.",
      "first_supported_at": "test-strategy",
      "basis": "Event 34 defines the named prerequisite, owner, approved sandbox, contract evidence and revalidation boundary. Plan Improve did not originate this decision."
    },
    {
      "decision": "Record actual execution of the local full-suite and focused entry points.",
      "first_supported_at": "test-strategy",
      "basis": "Events 24 and 28 retain exit-zero outputs naming the single offline-exception test. These establish runner and selector behavior only."
    },
    {
      "decision": "Require independent live observations for success, partial failure, interruption, retry and recovery.",
      "first_supported_at": "test-strategy",
      "basis": "Events 34 and 37 define S01–S04 and their old/new-state and operation-identity oracles, explicitly marked planned and not replayed."
    },
    {
      "decision": "Allocate W1 → W2 and independent W3, with W2 + W3 required by W4.",
      "first_supported_at": "plan-producer",
      "basis": "Events 81 and 86 establish the four-item queue, concrete readiness conditions and unresolved external supplier."
    },
    {
      "decision": "Explicitly distinguish sandbox acceptance execution from general publication activation.",
      "first_supported_at": "plan-improve",
      "basis": "Event 106 adds that distinction to W4 and architecture. This is a planning clarification, not empirical service evidence; the seed already included an approved opt-in live-test route."
    },
    {
      "decision": "Whether the real service and integrated command satisfy the required publication guarantees.",
      "first_supported_at": "unknown",
      "basis": "No approved sandbox, service contract or implemented command is supplied. All live acceptance remains due."
    }
  ],
  "summary": "All five planning obligations are fulfilled. The seed already made the consequential local-versus-service separation and correctly required no capability experiment. Review clarified activation wording, with uncertain incremental decision value. No product or live-service readiness is falsely claimed.",
  "limitations": [
    "Validation, preview and integration remain unimplemented; their planned tests provide no empirical feature evidence.",
    "The service contract, approved access, fault routes and actual live outcomes remain unknown.",
    "Receipt completion and structural checks support planning-process completion, not application acceptance."
  ]
}
